"""Selected student projects. Student credit is separate from the tutor's portfolio."""
from html import escape

STUDENTS = [
    dict(id='leona-rebooting', title='Rebooting Her World', student='Leona · Jinze Li', school='RCA · DD', medium='VR game & documentary narrative', image='leona-rebooting.jpg', width=1100, height=469, description='An immersive journey that looks beyond the role of “mother” to rediscover a woman’s individuality. Game environments and documentary storytelling bring personal memory, identity and lived experience into dialogue.', extra='The project develops a sequence of narrative spaces, from an insect factory and cage imagery to a chapel and underwater ruins. A later documentary extends the work into lived experience.', detail='leona-vr-scenes.jpg', alt='Selected scenes from Leona’s VR narrative Rebooting Her World.', video='iMrKAE7cm3c'),
    dict(id='april-hollow-echo', title='Hollow Echo', student='April · Yurou Zheng', school='USC · IDBT', medium='TouchDesigner spatial experience', image='april-hollow-echo.jpg', width=1100, height=469, description='A spatial experience about the self beneath external expectations. Balloons, moving images and audience interaction trace a journey from pressure and emptiness toward awareness and personal agency.', extra='Monochrome balloons carrying faces give way to coloured balloons as the narrative shifts from external voices toward self-expression. The documented setup includes Kinect recognition, interactive video switching and a physical installation.', detail='april-installation.jpg', alt='April’s Hollow Echo installation, with physical balloons, projection and audience interaction.', video='aDucCB3lxP8'),
    dict(id='leona-borrowed-face', title='The Borrowed Face', student='Leona · Jinze Li', school='RCA · DD', medium='Narrative moving image & circular screen', image='leona-borrowed-face.jpg', width=1300, height=553, description='An exploration of social masks and the shifting construction of identity. A purple-toned moving-image narrative unfolds across a circular screen and mirrored floor, placing the viewer within a field of projections and reflections.', extra='The work follows a cycle from the individual to the group and society, then back to the self. Masks become images to confront and reshape, rather than only disguises to wear.', detail='leona-ring-screen.jpg', alt='The Borrowed Face shown on a circular screen with a mirrored floor.', video='-Bkdr-86MYk'),
    dict(id='zhijun-moodblock', title='MoodBlock', student='Zhijun Chen', school='PolyU', medium='AR play & creative expression', image='zhijun-moodblock.jpg', width=1800, height=766, description='An AR-based creative app exploring emotional expression through virtual block-building and graffiti. Users create, customise and share playful spatial artworks through a purple-toned interface.', extra='The documented concept combines AR creation, mood-related interaction and a social space for sharing artworks. The project connects playful digital making with individual expression and sharing.', detail='zhijun-moodblock-outcome.png', alt='MoodBlock final outcomes: AR block-building, brush and water-ball tools, and mobile app interfaces by Zhijun Chen.', video='fTcCpifvVmM'),
]

STUDENTS += [
    dict(id='xueyi-cafe-muller', title='Café Müller', student='Xueyi He', school='Cornell University', medium='Web art & interactive storytelling', image='xueyi-cafe-muller.jpg', width=1600, height=681, description='A red-and-black web artwork that reinterprets Pina Bausch’s Café Müller through interactive, stream-of-consciousness storytelling about intimacy, uncertainty and modern relationships.', extra='The project translates the atmosphere of the original dance work into a sequence of browser-based encounters, combining collage, visual composition, narrative and interaction design.', detail='xueyi-web-art.jpg', alt='Selected red-and-black screens from Xueyi He’s Café Müller web artwork.', video='pwYG6pWZFAE'),
    dict(id='binyan-no-smoking', title='No Smoking! Pet', student='Binyan Wang', school='USC · IDBT', medium='Playful interaction & wearable concept', image='binyan-no-smoking.jpg', width=1600, height=687, description='A pet-raising app and wearable concept exploring support for women who are quitting smoking. Playful care routines, progress tracking and gentle prompts connect everyday interaction with the quitting journey.', extra='The documented group project brings together research, UX design, front-end implementation and user testing. Its design concept combines phone and watch interfaces with a warming belt and virtual pet activities.', detail='binyan-app.jpg', alt='Phone and watch interfaces from Binyan Wang’s No Smoking! Pet project.', video=None),
    dict(id='xiuyi-entrepreneurship', title='Future Entrepreneurship', student='Xiuyi Jia', school='CMU · ETC', medium='Entrepreneurship platform & service design', image='xiuyi-entrepreneurship.jpg', width=1600, height=680, description='A yellow-toned community platform concept supporting students as they explore entrepreneurship. It connects playful learning with resources for venue rental, second-hand trading, legal assistance and financing.', extra='The project maps entrepreneurial motivations and practical barriers into service features, a game-like learning journey and mobile interfaces. The illustrated character and warm palette create a recognisable entry point into a complex process.', detail='xiuyi-app.jpg', alt='User journey and mobile interfaces for Xiuyi Jia’s Future Entrepreneurship platform.', video=None),
    dict(id='haoyang-inside-my-mind', title='Inside My Mind', student='Haoyang Li', school='NYU · Game Design', medium='3D narrative puzzle game', image='haoyang-inside-my-mind.jpg', width=1600, height=681, description='A 3D interactive story about emotional exhaustion. Playing as a mind operator, the player explores malfunctioning rooms, gathers evidence and solves puzzles to uncover the source of a young woman’s worries.', extra='The game uses the mind as an explorable environment. Its rooms and narrative choices ask whether confronting a difficulty and removing its source are really the same thing. The portfolio documents level design, character and scene development, dialogue and implementation.', detail='haoyang-game-scenes.jpg', alt='Final game environments and dialogue scenes from Haoyang Li’s Inside My Mind.', video=None),
]

def selected_student_work():
    cards=[]
    for p in STUDENTS:
        detail = f'<figure><img src="assets/students/{p["detail"]}" alt="{escape(p["alt"])}" loading="lazy"><figcaption>Project documentation · {escape(p["student"])}</figcaption></figure>' if p['detail'] else ''
        video = f'<a class="text-link" href="https://www.youtube.com/watch?v={p["video"]}" target="_blank" rel="noopener noreferrer">Watch student project ↗</a>' if p['video'] else ''
        cards.append(f'''<article class="student-card" id="{p['id']}"><a class="student-image-link" href="assets/students/{p['image']}" target="_blank" rel="noopener" aria-label="View {escape(p['title'])} project image"><img class="student-cover" src="assets/students/{p['image']}" width="{p['width']}" height="{p['height']}" alt="{escape(p['title'])} — project cover by {escape(p['student'])}" loading="lazy"></a><div class="student-card-content"><p class="eyebrow">{p['medium']}</p><h3>{p['title']}</h3><p class="student-credit"><strong>Student: {p['student']}</strong><span>{p['school']}</span></p><p class="muted">{p['description']}</p><details><summary>Explore the project</summary><p>{p['extra']}</p>{detail}{video}</details></div></article>''')
    return '''<section class="section student-work" id="student-work" aria-labelledby="student-work-title"><div class="section-head"><div><p class="eyebrow">Selected student work / 学生作品指导</p><h2 id="student-work-title">Different voices.<br>A shared curiosity.</h2></div></div><p class="lead">A selection of student projects from my teaching practice, spanning VR, spatial storytelling, moving image and AR.</p><p class="student-attribution">Creative work is credited to the students below. These projects are presented as student work from my teaching practice, separately from my own portfolio.</p><div class="student-grid">''' + ''.join(cards) + '</div></section>'
